// #32: adaptar entradas; no filtrar pagos ni decidir abonos.
const input = $json;
const isForm = Object.prototype.hasOwnProperty.call(input, 'asunto') || Object.prototype.hasOwnProperty.call(input, 'cuerpo');
const text = value => typeof value === 'string' ? value.replace(/\r\n?/g, '\n') : '';
const asunto = text(isForm ? input.asunto : input.subject);
const cuerpo = text(isForm ? input.cuerpo : (input.textPlain || input.text));
const referencia = text(isForm ? input.referencia : (input.messageId || input.metadata?.['message-id'])).trim();
let motivo = '';
if (!asunto.trim() || !cuerpo.trim()) motivo = 'Falta asunto o cuerpo de texto plano; revisar la entrada';
else if (!referencia) motivo = 'Falta referencia de prueba o Message-ID del correo';
else if (cuerpo.length > 20000 || asunto.length > 998 || referencia.length > 300) motivo = 'Entrada demasiado larga; revisar sin procesar automáticamente';
return {json: {origen: isForm ? 'formulario' : 'imap', referencia, asunto, cuerpo, entrada_valida: !motivo, motivo}};
